'use client'
import React from 'react'

export default function Home() {
  return (
    <main className="min-h-screen bg-[#020202] text-white font-sans relative overflow-hidden flex flex-col md:flex-row">
      
      {/* FONDO CIUDAD: Mar del Plata Nocturna */}
      <div className="absolute inset-0 z-0 pointer-events-none opacity-30">
        <div 
          className="absolute inset-0 bg-cover bg-center mix-blend-overlay"
          style={{ backgroundImage: "url('https://images.unsplash.com/photo-1623945359620-8049103cc10e?auto=format&fit=crop&w=2000&q=80')" }}
        />
        <div className="absolute inset-0 bg-gradient-to-b from-black/20 via-black/80 to-black" />
      </div>

      {/* SECCIÓN IZQUIERDA: FÚTBOL */}
      <section className="relative flex-1 group overflow-hidden border-b md:border-b-0 md:border-r border-white/10 bg-green-950/20">
        <div 
          className="absolute inset-0 bg-cover bg-center grayscale group-hover:grayscale-0 group-hover:scale-105 transition-all duration-1000 ease-in-out"
          style={{ backgroundImage: "url('https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=1200&q=80')" }}
        />
        <div className="absolute inset-0 bg-[#020202]/60 group-hover:bg-[#020202]/20 transition-all duration-700" />
        
        <div className="relative z-10 h-full flex flex-col items-center justify-center p-12 text-center">
          <div className="mb-4">
            <span className="text-green-500 font-black italic tracking-[0.4em] text-[10px] uppercase">MDQ Stadium</span>
            <div className="h-[2px] w-8 bg-green-500 mt-1 mx-auto" />
          </div>
          <h2 className="text-6xl md:text-8xl font-black italic uppercase tracking-tighter mb-10 drop-shadow-2xl">
            FÚT<span className="text-green-500">BOL</span>
          </h2>
          <a 
            href="/reservar" 
            className="bg-white text-black font-black px-12 py-5 rounded-2xl uppercase italic text-[12px] hover:bg-green-500 hover:text-black transition-all shadow-xl active:scale-95"
          >
            Reservar Turno
          </a>
        </div>
      </section>

      {/* SECCIÓN DERECHA: PÁDEL */}
      <section className="relative flex-1 group overflow-hidden bg-blue-950/20">
        <div 
          className="absolute inset-0 bg-cover bg-center grayscale group-hover:grayscale-0 group-hover:scale-105 transition-all duration-1000 ease-in-out"
          style={{ backgroundImage: "url('https://images.unsplash.com/photo-1626225443592-fac438183180?auto=format&fit=crop&w=1200&q=80')" }}
        />
        <div className="absolute inset-0 bg-[#020202]/60 group-hover:bg-[#020202]/20 transition-all duration-700" />
        
        <div className="relative z-10 h-full flex flex-col items-center justify-center p-12 text-center">
          <div className="mb-4">
            <span className="text-blue-500 font-black italic tracking-[0.4em] text-[10px] uppercase">Padel Center</span>
            <div className="h-[2px] w-8 bg-blue-500 mt-1 mx-auto" />
          </div>
          <h2 className="text-6xl md:text-8xl font-black italic uppercase tracking-tighter mb-10 drop-shadow-2xl">
            PÁ<span className="text-blue-500">DEL</span>
          </h2>
          <a 
            href="/armar-desafio" 
            className="bg-blue-600 text-white font-black px-12 py-5 rounded-2xl uppercase italic text-[11px] hover:bg-white hover:text-black transition-all shadow-xl active:scale-95"
          >
            Arena de Desafíos
          </a>
        </div>
      </section>

      {/* INDICADOR CENTRAL MDQ */}
      <div className="absolute top-8 left-1/2 -translate-x-1/2 z-30 hidden md:block">
        <div className="bg-black/60 backdrop-blur-md border border-white/10 px-8 py-3 rounded-full">
          <p className="text-[9px] font-black uppercase tracking-[0.6em] text-white/80">
            Mar del Plata <span className="text-green-500 mx-3">•</span> 2026
          </p>
        </div>
      </div>

      <div className="absolute top-8 right-8 z-30">
        <a href="/dashboard" className="text-xl bg-black/40 p-3 rounded-xl border border-white/10 hover:bg-white transition-all">⚙️</a>
      </div>

    </main>
  )
}